// multisoul-pi-extension-marker
// Auto-generated by Norma OS. Forwards Pi lifecycle events to the local Norma app.
// Fail-open: any error or missing environment is swallowed so Pi is never blocked.

function str(value) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function toolLabel(value) {
  const raw = str(value) || "tool";
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

function replyText(message) {
  if (!Array.isArray(message?.content)) return str(message?.content);
  const parts = message.content
    .filter((part) => part && part.type === "text" && str(part.text))
    .map((part) => part.text);
  return parts.length > 0 ? parts.join("\n") : undefined;
}

const PATH_CONVENTION = __NORMA_PATH_CONVENTION__;

let queue = Promise.resolve();

function post(providerEvent, ctx, extra = {}) {
  const nodeID = Number(process.env.MULTISOUL_NODE_ID);
  const endpoint = process.env.MULTISOUL_HOOK_ENDPOINT;
  const token = process.env.MULTISOUL_HOOK_TOKEN;
  if (!Number.isFinite(nodeID) || !endpoint || !token) return undefined;

  let sessionId;
  let cwd;
  try {
    sessionId = str(ctx?.sessionManager?.getSessionId?.());
    cwd = str(ctx?.cwd);
  } catch {
    // Context probing must never break Pi.
  }
  const rawJson = { hook_event_name: providerEvent, session_id: sessionId, cwd, ...extra.raw };
  const body = {
    node_id: nodeID,
    profile: "Pi",
    provider_event: providerEvent,
    session_id: sessionId,
    turn_id: str(extra.turnId),
    tool_name: str(extra.toolName),
    message: str(extra.message),
    raw_json: rawJson,
  };
  // Serialise sends so Norma sees events in Pi's order, without making Pi wait on the network.
  queue = queue.then(async () => {
    try {
      await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(300),
      });
    } catch {
      // Fail open: Pi must never block on Norma OS being unavailable.
    }
  });
  return queue;
}

export default function (pi) {
  let runSeq = 0;
  let turnId;
  let lastReply;
  let lastError;

  const on = (name, handler) => {
    pi.on(name, (event, ctx) => {
      try {
        return handler(event || {}, ctx);
      } catch {
        // Fail open.
        return undefined;
      }
    });
  };

  on("session_start", (_event, ctx) => {
    post("SessionStart", ctx);
  });

  on("before_agent_start", (event, ctx) => {
    runSeq += 1;
    turnId = `pi-run-${runSeq}`;
    lastReply = undefined;
    lastError = undefined;
    const prompt = str(event.prompt);
    post("UserPromptSubmit", ctx, { turnId, raw: prompt ? { prompt } : {} });
    // Norma 托管会话：在本轮 system prompt 末尾追加文件路径输出约定。
    if (
      Number.isFinite(Number(process.env.MULTISOUL_NODE_ID)) &&
      process.env.NORMA_PATH_CONVENTION !== "0" &&
      str(event.systemPrompt)
    ) {
      return { systemPrompt: `${event.systemPrompt}\n\n${PATH_CONVENTION}` };
    }
    return undefined;
  });

  on("tool_call", (event, ctx) => {
    const toolName = toolLabel(event.toolName);
    post("PreToolUse", ctx, {
      turnId,
      toolName,
      raw: { tool_name: toolName, tool_input: event.input },
    });
  });

  on("tool_result", (event, ctx) => {
    const toolName = toolLabel(event.toolName);
    if (event.isError === true) {
      post("PostToolUseFailure", ctx, { turnId, toolName, message: "Pi tool failed" });
    } else {
      post("PostToolUse", ctx, { turnId, toolName });
    }
  });

  on("turn_end", (event) => {
    const message = event.message;
    if (message?.stopReason === "error" || str(message?.errorMessage)) {
      lastError = str(message?.errorMessage) || "Pi turn failed";
      return;
    }
    if (message?.stopReason === "toolUse") return;
    const text = replyText(message);
    if (text) lastReply = text;
  });

  on("agent_settled", (event, ctx) => {
    if (event.aborted === true || lastError) {
      post("StopFailure", ctx, {
        turnId,
        message: lastError || "Pi run aborted",
      });
      return;
    }
    post("Stop", ctx, {
      turnId,
      raw: lastReply ? { last_assistant_message: lastReply } : {},
    });
  });

  // Pi also emits session_shutdown for reload/new/resume/fork while the process stays alive
  // (SessionShutdownEvent.reason in pi-coding-agent types); only "quit" means the process exits.
  // Awaited (bounded by the 300ms fetch timeout) so the event is flushed before Pi exits.
  on("session_shutdown", (event, ctx) => {
    if (event.reason !== "quit") return undefined;
    return post("SessionEnd", ctx);
  });
}
